const copy=structuredClone,locked={move:false,resize:false,layer:false,edit:false,remove:false};
export function pageBlockRegistry(){const r=manifestRegistry();for(const type of ['application','dynamic'])r.register({type,version:1,label:type==='application'?'Protected application':'Dynamic content',icon:'◇',minCols:1,minRows:1,capabilities:locked,validate:c=>typeof c.binding==='string'&&typeof c.source==='string'});return r;}
function inline(node,marks=[]){if(node.nodeType===3)return node.textContent?[{type:'text',text:node.textContent,...marks.length?{marks:copy(marks)}:{}}]:[];if(node.nodeType!==1)return [];const tag=node.tagName.toLowerCase();if(tag==='br')return [{type:'hard_break'}];let next=marks;if(['em','i','strong','b','code','a'].includes(tag)){const type={i:'em',b:'strong',a:'link'}[tag]||tag;if(type!=='link'||contentURL(node.getAttribute('href')))next=[...marks,{type,...type==='link'?{attrs:{href:contentURL(node.getAttribute('href'))}}:{}}];}return [...node.childNodes].flatMap(n=>inline(n,next));}
export async function bootstrapPage(route,mapping,html,document){const parsed=new document.defaultView.DOMParser().parseFromString(html,'text/html'),id='page:'+routeKey(route),body={version:1,slots:{content:{type:'doc',content:[]}}},manifest={schemaVersion:1,id,sections:[]},bindings={},assets=[],usage=[];
 for(const spec of mapping.sections){const section=parsed.querySelector(spec.selector);if(!section){if(spec.optional)continue;throw Error('Canonical page binding is missing: '+spec.id);}const sid=id+':section:'+spec.id,s={id:sid,policy:'layer',order:[],blocks:{},layouts:Object.fromEntries(['desktop','mobile'].map(bp=>[bp,{grid:{...defaultGrid(),columns:bp==='mobile'?8:24},rows:spec.fallbackRows?.[bp]||16,placements:{}}]))};let i=0;
  for(const bspec of spec.protected?[{id:'protected',type:spec.source==='application'?'application':'dynamic',source:spec.source,selector:null}]:spec.blocks){const el=bspec.selector?section.querySelector(bspec.selector):section;if(!el){if(bspec.optional)continue;throw Error('Canonical block binding is missing: '+bspec.id);}const bid=sid+':'+bspec.id,type=bspec.type;let content,presentation={};if(type==='text'){const path=[body.slots.content.content.length];body.slots.content.content.push({type:'paragraph',content:inline(el)});content={slot:'content',path,kind:'paragraph',ref:null};}else if(type==='button'){content={label:el.textContent.trim(),href:el.getAttribute('href')};presentation={variant:el.classList.contains('button-secondary')?'secondary':'primary'};}else if(type==='image'){const assetId='static:'+bspec.asset;assets.push({id:assetId,path:bspec.asset,filename:bspec.asset.split('/').at(-1)});usage.push({document_id:id,article_id:id,asset_id:assetId,block_ref:bid,alt_text:el.getAttribute('alt')||''});content={assetId,usageRef:bid};presentation={fit:'cover'};}else content={binding:bid,source:bspec.source};
   const isProtected=['application','dynamic'].includes(type);s.order.push(bid);s.blocks[bid]={id:bid,type,version:1,content,presentation,capabilities:isProtected?locked:{move:true,resize:true,layer:true,edit:true,remove:false}};bindings[bid]={sectionId:sid,selector:bspec.selector,sectionSelector:spec.selector,tag:el.tagName,original:el.innerHTML,initial:copy(s.blocks[bid]),source:bspec.source,isProtected};
   for(const [bp,l] of Object.entries(s.layouts)){const a=bspec[bp]||[0,i*4,l.grid.columns,Math.min(isProtected?8:4,l.rows)],p={col:a[0],row:a[1],cols:a[2],rows:a[3],z:type==='image'?0:i+1,visible:true,locked:isProtected};l.rows=Math.max(l.rows,p.row+p.rows+l.grid.trailingRows);l.placements[bid]={source:'generated',value:p};}i++;
  }manifest.sections.push(s);
 }
 if(!body.slots.content.content.length)body.slots.content.content.push({type:'paragraph',content:[{type:'text',text:'Private presentation'}]});const source=canonical({route,mappingVersion:1,body,blocks:manifest.sections.map(s=>s.order.map(id=>s.blocks[id]))}),hash=[...new Uint8Array(await document.defaultView.crypto.subtle.digest('SHA-256',new TextEncoder().encode(source)))].map(x=>x.toString(16).padStart(2,'0')).join('');const record={id,document_key:routeKey(route),route,document_type:mapping.type,source_hash:hash,draft:{body},manifest,edit_version:0};return {descriptor:documentDescriptor({route,type:mapping.type,title:mapping.title,record}),record,bindings,assets,usage,presentation:{refs:{},slots:[],style:'native'},baseline:copy(manifest)};
}
export function validatePageComposition(doc,body,id,{assets=[]}={}){validateDocument(doc,pageBlockRegistry());if(doc.id!==id)throw Error('Wrong document identity.');for(const s of doc.sections)for(const b of Object.values(s.blocks)){if(b.type==='text')semanticNode(b,body);if(b.type==='image'&&!assets.some(a=>a.id===b.content.assetId))throw Error('Image requires approved media.');if(['application','dynamic'].includes(b.type)&&Object.values(b.capabilities).some(Boolean))throw Error('Protected content cannot be edited.');}return doc;}
export function pageTextHTML(b,body,presentation){const n=semanticNode(b,body);return renderBody({type:'doc',content:[n]},presentation,b.content.slot);}
